// Config global del bot
const config = {
  // JID del grupo REMITOS
  groupJid: '120363039852043503@g.us',

  // ID del Google Sheet (de la URL: docs.google.com/spreadsheets/d/<ESTE_ID>/edit)
  spreadsheetId: '1dLd0fgqVrDLliq4sCdVxMtXdavWuREkEeZcODDk-t8Y',

  // Evolution API (instancia self-hosted en EasyPanel)
  evolutionApiUrl: 'https://evolutioapi-evolution-api.mknton.easypanel.host',
  evolutionInstance: 'winndia-bot',

  // Mapa de alias de cliente -> nombre exacto de la hoja en el Sheet.
  // Agregá aliases para cada cliente con todas las formas en que puede aparecer en remitos/comprobantes.
  clientAliases: {
    'ramiro rendon': 'ROCAS RAMIRO',
    'ramiro rendón': 'ROCAS RAMIRO',
    'rodriguez rendon ramiro': 'ROCAS RAMIRO',
    'cinna': 'CINNA',
    'veggia': 'VEGGIA',
    'fatima kuns': 'FATIMA KUNS',
    'bucco': 'BUCCO',
    'indara estefi': 'INDARA ESTEFI',
    'bloomchic': 'BLOOMCHIC',
    'tosco': 'TOSCO',
    'you are by alexia': 'YOU ARE BY ALEXIA',
    'niusta': 'NIUSTA',
    'principito': 'PRINCIPITO',
    'margarita': 'MARGARITA',
    'zapin': 'zapin',
    'de pueblo': 'de pueblo',
    'daielo': 'daielo'
  }
};

// El webhook de n8n envuelve el payload en .body — desempaquetamos acá
// para que los nodos siguientes accedan a campos como original.data.key.remoteJid directamente.
const webhookInput = $input.first().json;
const original = webhookInput.body || webhookInput;

return [{ json: { config, original } }];

// Parseamos respuesta de Claude, matcheamos cliente y decidimos acción
const claudeResp = $input.first().json;
const rawText = claudeResp.content?.[0]?.text || '{}';

let extracted;
try {
  const cleaned = rawText.replace(/^```json\s*/i, '').replace(/```\s*$/, '').trim();
  extracted = JSON.parse(cleaned);
} catch (e) {
  extracted = { tipo: 'irrelevante', faltante: 'No se pudo parsear: ' + rawText.slice(0, 100), confianza: 'baja' };
}

const configItem = $('Config').first().json;
const aliases = configItem.config.clientAliases;
const original = configItem.original;

// Si es irrelevante, no respondemos nada al grupo (acción: ignorar)
if (extracted.tipo === 'irrelevante') {
  return [{
    json: {
      extracted,
      accion: 'ignorar',
      config: configItem.config,
      groupJid: configItem.config.groupJid
    }
  }];
}

// Categorías por tipo
const esRemito = extracted.tipo === 'remito_cta1' || extracted.tipo === 'remito_cta2';
const esNDC = extracted.tipo === 'ndc_cta1' || extracted.tipo === 'ndc_cta2';
const esTransferencia = extracted.tipo === 'pago_transferencia';
const esCheque = extracted.tipo === 'pago_cheque';
const esEcheq = extracted.tipo === 'pago_echeq';
const esPago = esTransferencia || esCheque || esEcheq;

// Cuenta según tipo:
// - remito/NDC oficial → cta 1
// - remito/NDC presupuesto → cta 2
// - echeq → cta 1 (echeqs son siempre cta 1)
// - cheque físico → cta 2 (cheques físicos siempre cta 2)
// - transferencia → indefinida hasta que llegue el contexto (Fase 2)
let cuenta = null;
if (extracted.tipo === 'remito_cta1' || extracted.tipo === 'ndc_cta1' || esEcheq) cuenta = 1;
else if (extracted.tipo === 'remito_cta2' || extracted.tipo === 'ndc_cta2' || esCheque) cuenta = 2;
// pago_transferencia: cuenta se determina al recibir el mensaje de contexto del cliente

// Match de cliente — SOLO para remitos y NDC. Pagos vienen sin cliente desde la imagen.
function normalize(s) {
  return (s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9 ]/g, '').trim();
}

let sheetName = null;
if ((esRemito || esNDC) && extracted.cliente_detectado) {
  const detected = normalize(extracted.cliente_detectado);
  for (const [alias, sheet] of Object.entries(aliases)) {
    if (detected.includes(normalize(alias)) || normalize(alias).includes(detected)) {
      sheetName = sheet;
      break;
    }
  }
}

// Decisión de acción
// Fase 1: pagos sin cliente del grupo aún no son procesables, los marcamos como 'preguntar' para que el equipo sepa
// Fase 2 los va a manejar bien con la pestaña Pendientes
let accion;
if (esPago) {
  accion = 'preguntar_pago'; // bot pregunta cliente/cta porque pago vino sin contexto suficiente
} else if ((esRemito || esNDC) && sheetName && cuenta && extracted.monto && extracted.confianza === 'alta') {
  accion = 'cargar';
} else if (esRemito || esNDC) {
  accion = 'preguntar';
} else {
  accion = 'ignorar';
}

return [{
  json: {
    extracted,
    sheetName,
    cuenta,
    esRemito,
    esNDC,
    esTransferencia,
    esCheque,
    esEcheq,
    esPago,
    accion,
    config: configItem.config,
    senderJid: original.data.key.participant || original.data.key.remoteJid,
    messageId: original.data.key.id,
    groupJid: configItem.config.groupJid
  }
}];

// Arma la fila a escribir según tipo + cuenta
const d = $input.first().json;
const e = d.extracted;

// cta 2 → A:E (FECHA, COMPROBANTE, NOTA, DEBE, HABER) — SALDO en F no la tocamos
// cta 1 → H:L (mismo orden, M es SALDO y no la tocamos)
const rangeStart = d.cuenta === 1 ? 'H' : 'A';
const rangeEnd = d.cuenta === 1 ? 'L' : 'E';

// DEBE vs HABER
// - Remito normal → DEBE
// - NDC → HABER (es nota de crédito, descuenta deuda)
// - Pago (cheque/echeq/transferencia) → HABER
let debe = '';
let haber = '';
if (d.esNDC || d.esPago) {
  haber = e.monto;
} else {
  debe = e.monto;
}

// Comprobante
// - Transferencia → 'PAGO' literal
// - Cheque/Echeq/Remito/NDC → número del documento
let comprobante;
if (d.esTransferencia) {
  comprobante = 'PAGO';
} else {
  comprobante = e.numero_comprobante || '';
}

// Nota
// - NDC → siempre arrancar con 'NDC'
// - Otros → nota_corta del modelo (puede estar vacía)
let nota = e.nota_corta || '';
if (d.esNDC) {
  nota = nota ? `NDC ${nota}` : 'NDC';
}

return [{
  json: {
    ...d,
    sheetRange: `${d.sheetName}!${rangeStart}:${rangeEnd}`,
    rowValues: [e.fecha || '', comprobante, nota, debe, haber]
  }
}];

